&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p style="text-align:center"&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Pacific Power warns customers about billing scams&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
